{"content":"// compareVersions(a, b) → -1, 0 or 1 following Semantic Versioning 2.0.0 precedence
// (including pre-release identifiers; build metadata after '+' is ignored).
export function compareVersions(a, b) {
  const pa = parseVersion(a);
  const pb = parseVersion(b);
  for (let i = 0; i < 3; i++) {
    if (pa.core[i] !== pb.core[i]) return pa.core[i] < pb.core[i] ? -1 : 1;
  }

  if (!pa.prerelease.length || !pb.prerelease.length) {
    if (pa.prerelease.length) return -1;
    if (pb.prerelease.length) return 1;
    return 0;
  }

  for (let i = 0; i < Math.min(pa.prerelease.length, pb.prerelease.length); i++) {
    const left = pa.prerelease[i];
    const right = pb.prerelease[i];
    if (left === right) continue;
    const leftNumeric = /^[0-9]+$/.test(left);
    const rightNumeric = /^[0-9]+$/.test(right);
    if (leftNumeric !== rightNumeric) return leftNumeric ? -1 : 1;
    if (leftNumeric) return BigInt(left) < BigInt(right) ? -1 : 1;
    return left < right ? -1 : 1;
  }

  if (pa.prerelease.length === pb.prerelease.length) return 0;
  return pa.prerelease.length < pb.prerelease.length ? -1 : 1;
}

function parseVersion(version) {
  const withoutBuild = version.split('+', 1)[0];
  const separator = withoutBuild.indexOf('-');
  const core = separator === -1 ? withoutBuild : withoutBuild.slice(0, separator);
  return {
    core: core.split('.').map(part => BigInt(part)),
    prerelease: separator === -1 ? [] : withoutBuild.slice(separator + 1).split('.'),
  };
}
